function ZT_vmSelftest() {
  var micro = ZT_buildMicroVM(ZT_MICRO_OPS, 233);
  var microRun = ZT_vmExec(micro, [7, 11, 13, 17]);
  ZT_check('jsvmp-micro-halt', microRun.halted === true, microRun.steps);
  ZT_check('jsvmp-micro-chain', microRun.chain === 1824104099, microRun.chain);
  ZT_check('jsvmp-micro-reg', microRun.reg[0] === 2960023930, microRun.reg[0]);

  var innerDecoded = ZT_decodeProgram(ZT_CODE_IN);
  var inner = ZT_buildVM(innerDecoded, 38, 'inner');
  inner.inner = function (x) {
    var r = ZT_vmExec(micro, [x, 3, 5, 7]);
    return (r.reg[0] ^ r.chain) >>> 0;
  };
  var innerRun = ZT_vmExec(inner, [1, 2, 3, 4]);
  ZT_check('jsvmp-inner-halt', innerRun.halted === true, innerRun.steps);
  ZT_check('jsvmp-inner-chain', innerRun.chain === 4063551245, innerRun.chain);
  ZT_check('jsvmp-inner-ops', inner.count === 12800, inner.count);
  ZT_check('jsvmp-inner-steps', innerRun.steps === inner.count, innerRun.steps);

  var outerDecoded = ZT_decodeProgram(ZT_CODE_OUT);
  var outer = ZT_buildVM(outerDecoded, 184, 'outer');
  outer.inner = function (x) {
    var r = ZT_vmExec(inner, [x, 9, 21, 33]);
    return (r.reg[0] ^ r.chain ^ r.fault) >>> 0;
  };
  var outerRun = ZT_vmExec(outer, [5, 6, 7, 8]);
  ZT_check('jsvmp-outer-halt', outerRun.halted === true, outerRun.steps);
  ZT_check('jsvmp-outer-chain', outerRun.chain === 1360348206, outerRun.chain);
  ZT_check('jsvmp-outer-ops', outer.count === 240000, outer.count);
  ZT_check('jsvmp-outer-steps', outerRun.steps === outer.count, outerRun.steps);
  ZT_check('jsvmp-micro-steps', microRun.steps === micro.count, microRun.steps);
  ZT_check('jsvmp-outer-digest', outerDecoded.digest === 939563006, outerDecoded.digest);
  ZT_check('jsvmp-outer-faultless', outerRun.fault === 0, outerRun.fault);

  var total = outer.count + inner.count + micro.count;
  ZT_COUNT.jsvmpOps = total;
  var rerun = ZT_vmExec(outer, [5, 6, 7, 8]);
  ZT_check('jsvmp-deterministic', rerun.chain === outerRun.chain, rerun.chain);
  return { ok: ZT_TESTS.failed === 0, ops: total, outer: outerRun, inner: innerRun, micro: microRun };
}

