function ZT_antiDebug() {
  var out = [];
  function push(name, fn) {
    var value;
    try {
      value = fn();
    } catch (err) {
      value = 'error';
    }
    out.push({ name: name, ok: value === true, value: value });
  }
  push('timing-jitter', function () {
    var t0 = Date.now();
    var acc = 0;
    for (var i = 0; i < 4000; i++) acc = (acc + ((i * 31) ^ (acc >>> 3))) | 0;
    var dt = Date.now() - t0;
    return dt < 400;
  });
  push('stack-frames', function () {
    var e = new Error('probe');
    return typeof e.stack === 'string' && e.stack.length > 0;
  });
  push('native-hooks', function () {
    return String(Array.prototype.map).indexOf('[native code]') >= 0;
  });
  push('inspector-argv', function () {
    if (typeof process === 'undefined') return true;
    return String(process.execArgv || '').indexOf('inspect') < 0;
  });
  push('console-shape', function () {
    return typeof console === 'object' && typeof console.log === 'function' && typeof console.error === 'function';
  });
  push('prepare-stack-trap', function () {
    var prior = Error.prepareStackTrace;
    Error.prepareStackTrace = function (err, frames) {
      return frames;
    };
    var e = new Error('trap');
    var frames = e.stack;
    Error.prepareStackTrace = prior;
    return Array.isArray(frames);
  });
  push('debugger-statement', function () {
    var marker = 0;
    debugger;
    marker = (marker + 1) & 1;
    return marker === 1;
  });
  push('function-tostring', function () {
    return String(ZT_vmHandlers).indexOf('function') >= 0;
  });
  push('object-freeze-probe', function () {
    var o = Object.freeze({ a: 1 });
    return Object.isFrozen(o) === true && o.a === 1;
  });
  push('timer-drift', function () {
    var start = Date.now();
    var spins = 0;
    while (Date.now() - start < 1 && spins < 100000) spins += 1;
    return spins > 0;
  });
  return out;
}

