  ZT_COUNT.customCiphers = cipherCount;
  ZT_COUNT.encodings = encodingCount;
  ZT_check('whitebox-suite-count', whiteboxCount >= 3, whiteboxCount);
  ZT_check('cipher-suite-count', cipherCount >= 3, cipherCount);
  ZT_check('encoding-suite-count', encodingCount >= 3, encodingCount);
  ZT_COUNT.mixedRounds = rounds;
  ZT_check('mixed-rounds-floor', rounds >= 1, rounds);

